#include "LiveData.h"
namespace injector_diagnostic {std::vector<LiveDataValue> LiveData::readAll()const{return {{LiveDataParameter::RPM,850.0,"rpm",true},{LiveDataParameter::CoolantTemperature,88.0,"C",true},{LiveDataParameter::TPS,12.5,"%",true},{LiveDataParameter::MAP,38.0,"kPa",true},{LiveDataParameter::MAF,3.2,"g/s",true},{LiveDataParameter::O2Sensor,0.72,"V",true},{LiveDataParameter::BatteryVoltage,13.9,"V",true}};}std::optional<LiveDataValue> LiveData::read(LiveDataParameter p)const{for(const auto& v:readAll())if(v.parameter==p)return v;return std::nullopt;}std::string LiveData::parameterName(LiveDataParameter p){switch(p){case LiveDataParameter::RPM:return "RPM";case LiveDataParameter::CoolantTemperature:return "Coolant Temperature";case LiveDataParameter::TPS:return "TPS";case LiveDataParameter::MAP:return "MAP";case LiveDataParameter::MAF:return "MAF";case LiveDataParameter::O2Sensor:return "O2 Sensor";case LiveDataParameter::BatteryVoltage:return "Battery Voltage";}return "Unknown";}}
